#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "esp_err.h"
#include "esp_http_server.h"
#include "hy/api.h"
#include "hy/routes.h"
#include "hy/web.h"

/* ---- static assets (generated by tools/web_bundle.py into the build directory) ---- */

typedef struct {
    const char *path;      /* "/index.html", "/app.<hash>.js", ... */
    const char *mime;
    const uint8_t *gz;     /* gzip */
    size_t len;
    bool immutable;        /* hashed name: max-age one year, immutable; else no-cache */
} hy_web_asset_t;

extern const hy_web_asset_t hy_web_assets[];
extern const size_t hy_web_assets_n;
extern const size_t hy_web_assets_bytes;

/* ---- one /api request, as the route handlers see it ---- */

#define WEB_BODY_MAX (16 * 1024)

/* Header buffers, shared by /api and /ws so both accept the same requests. A longer value is treated as absent. */
#define WEB_HDR_HOST   72
#define WEB_HDR_ORIGIN 128
#define WEB_HDR_COOKIE 512

typedef struct {
    httpd_req_t *req;
    const hy_route_t *route;
    uint32_t id;           /* the "{id}" segment, 0 when the route has none */
    char *body;            /* NUL-terminated, PSRAM; "" when the request has none; freed by the dispatcher */
    size_t body_len;
    int sess;              /* session slot of the caller, -1 when unpaired */
    int status;            /* set by the web_send_* helpers */
} web_req_t;

typedef esp_err_t (*web_handler_t)(web_req_t *r);

/* "Cache-Control: no-store" and the JSON type are set on every answer. */
esp_err_t web_send_json(web_req_t *r, int status, const char *json);
/* {"error":"<code>","field":..,"message":..}; field and message may be NULL */
esp_err_t web_send_err(web_req_t *r, int status, const char *code, const char *field, const char *message);
/* hy_api_err_from mapping */
esp_err_t web_send_hy_err(web_req_t *r, hy_err_t e, const char *message);
/* 503 "busy" with Retry-After 2: a job timed out */
esp_err_t web_send_busy(web_req_t *r);
const char *web_status_line(int status);

/* Route handlers. h_core.c answers info, state, pairing and browsers, then asks each family below; NULL from all of
 * them: 501 "not_implemented". The families are weak in h_core.c (NULL) and defined by their own files; the component
 * links as a whole archive so a strong definition always wins. */
web_handler_t web_route_handler(hy_route_id_t id);
web_handler_t web_meds_route(hy_route_id_t id);       /* medicines, pills, dose actions */
web_handler_t web_log_route(hy_route_id_t id);        /* log, history, schedule */
web_handler_t web_settings_route(hy_route_id_t id);   /* settings, time, chime, power off */
web_handler_t web_wifi_route(hy_route_id_t id);       /* Wi-Fi */
web_handler_t web_data_route(hy_route_id_t id);       /* export, import, firmware update */

/* Host name, IP literals and AP mode of the moment (hy_net_status copy). */
typedef struct {
    bool ap;
    char ip[16];
    char host[33];
} web_net_t;
void web_net_now(web_net_t *out);

/* ---- UI side (server.c) ---- */

/* Runs the registered callback in the LVGL task. Text arguments must be static. */
void web_ui_pair_show(void);
void web_ui_pair_hide(int reason);
void web_ui_toast_ok(const char *text);
void web_ui_toast_info(const char *text);

/* ---- pairing state (h_core.c) ---- */

void web_pair_init(void);
/* Under the pairing lock: the running code and its expiry, false when none runs */
bool web_pair_peek(char code[7], int64_t *expires_mono);

/* ---- sessions (session.c) ---- */

#define WEB_SESS_MAX 4
#define WEB_LABEL_LEN 24

typedef struct {
    int slot;
    int64_t created;       /* wall clock seconds, 0 when the clock was invalid */
    char label[WEB_LABEL_LEN];
} web_sess_info_t;

esp_err_t web_sess_init(void);
/* The slot whose stored SHA-256 matches the hy_s cookie of the Cookie header (constant time over every slot), or -1.
 * *gen (may be NULL) receives the slot's generation, which changes whenever the slot is replaced or forgotten. */
int       web_sess_check(const char *cookie_header, uint32_t *gen);
/* Stores the hash of token (32 bytes) with a label from the User-Agent. A fifth browser replaces the oldest. */
esp_err_t web_sess_add(const uint8_t token[32], const char *user_agent, int *slot);
size_t    web_sess_list(web_sess_info_t *out, size_t max);
/* slot -1: all */
esp_err_t web_sess_forget(int slot);
size_t    web_sess_count(void);
bool      web_sess_valid(int slot, uint32_t gen);
/* SHA-256 through PSA */
esp_err_t web_sha256(const uint8_t *in, size_t len, uint8_t out[32]);

/* ---- WebSocket (ws.c) ---- */

void      web_ws_init(void);
/* After httpd_start / before httpd_stop */
void      web_ws_attach(httpd_handle_t srv);
void      web_ws_detach(void);
esp_err_t web_ws_register(httpd_handle_t srv);
/* httpd close_fn hook */
void      web_ws_on_close(int fd);
/* Closes live-event sockets whose session was forgotten (queued to the httpd task) */
void      web_ws_sessions_changed(void);
/* Queues fn to the httpd task when the server runs; false otherwise */
bool      web_queue_work(httpd_work_fn_t fn, void *arg);
#if CONFIG_HY_DEBUG_CONSOLE
void      web_ws_debug(void);
#endif

/* ---- host check shared by the handlers (server.c) ---- */

/* true when the Host header is allowed; else sends 302 to the portal (AP mode) or 421 and returns false. api: JSON
 * error body with no-store. */
bool web_host_check(httpd_req_t *req, const web_net_t *net, bool api);
